  /* ============================================================
     Übungsfragen mit ausdrücklichem Sprachniveau
     ------------------------------------------------------------
     Diese Fragen tragen ihr Niveau (A1–C2) selbst bei sich. Dadurch kann
     die Übungs-Engine wirklich nach Niveau filtern, statt es aus Kategorie
     und Satzlänge zu schätzen. Sie werden unten an die passenden
     Fragenbänke angehängt.
     ============================================================ */
  const EXERCISE_EXTRA = {
    zeitformen: [
      { prompt: "Gestern ___ ich zu Hause.", options: ["bin","war","werde"], correct: [1], explain: "„Gestern“ verlangt die Vergangenheit: „war“.", level: "A1" },
      { prompt: "Morgen ___ ich einkaufen.", options: ["gehe","ging","gegangen"], correct: [0], explain: "Im Deutschen steht für die nahe Zukunft oft einfach das Präsens: „Morgen gehe ich“.", level: "A1" },
      { prompt: "Wir ___ gestern im Kino.", options: ["sind","waren","werden"], correct: [1], explain: "Vergangenheit von „sein“ in der Wir-Form: „waren“.", level: "A1" },
      { prompt: "Ich habe das Buch schon ___.", options: ["lesen","gelesen","las"], correct: [1], explain: "Perfekt mit „haben“ braucht das Partizip II: „gelesen“.", level: "A2" },
      { prompt: "Als Kind ___ ich jeden Sommer ans Meer.", options: ["fuhr","fahre","gefahren"], correct: [0], explain: "Beim Erzählen aus der Kindheit steht das Präteritum: „fuhr“.", level: "B1" },
      { prompt: "Bevor er kam, ___ wir schon gegessen.", options: ["haben","hatten","werden"], correct: [1], explain: "Das Plusquamperfekt („hatten gegessen“) zeigt, was noch früher passiert ist.", level: "B2" },
      { prompt: "Hätte ich das gewusst, ___ ich anders entschieden.", options: ["hätte","würde","habe"], correct: [0], explain: "Irrealer Bedingungssatz der Vergangenheit: „hätte … entschieden“.", level: "C1" },
      { prompt: "Er behauptete, er ___ nichts davon gewusst.", options: ["hat","habe","hatte"], correct: [1], explain: "Indirekte Rede steht im Konjunktiv I: „habe“.", level: "C1" },
    ],
    nebensatz: [
      { prompt: "Ich bleibe zu Hause, ___ es regnet.", options: ["weil","denn","obwohl"], correct: [0], explain: "„weil“ nennt den Grund und schickt das Verb ans Ende.", level: "A2" },
      { prompt: "Ich weiß nicht, ___ er heute kommt.", options: ["ob","wenn","als"], correct: [0], explain: "Bei einer offenen Ja-/Nein-Frage steht „ob“.", level: "A2" },
      { prompt: "___ ich klein war, wohnten wir in Bremen.", options: ["Wenn","Als","Ob"], correct: [1], explain: "Ein einmaliger Zeitraum in der Vergangenheit: „als“.", level: "B1" },
      { prompt: "Er ging zur Arbeit, ___ er krank war.", options: ["obwohl","weil","damit"], correct: [0], explain: "„obwohl“ nennt einen Gegensatz zur Erwartung.", level: "B1" },
      { prompt: "Ich schreibe es auf, ___ ich es nicht vergesse.", options: ["damit","sodass","indem"], correct: [0], explain: "„damit“ nennt die Absicht.", level: "B2" },
      { prompt: "___ er gründlich vorbereitet war, scheiterte der Vortrag.", options: ["Obgleich","Sofern","Indem"], correct: [0], explain: "„Obgleich“ ist die gehobene Form von „obwohl“.", level: "C1" },
      { prompt: "___ keine Einwände bestehen, gilt der Antrag als angenommen.", options: ["Sofern","Obwohl","Nachdem"], correct: [0], explain: "„Sofern“ nennt eine Bedingung — typisch für Amtssprache.", level: "C1" },
    ],
    relativsatz: [
      { prompt: "Das ist der Mann, ___ hier wohnt.", options: ["der","den","dem"], correct: [0], explain: "Er ist das Subjekt des Nebensatzes → Nominativ „der“.", level: "A2" },
      { prompt: "Das ist das Buch, ___ ich gestern gekauft habe.", options: ["das","dem","dessen"], correct: [0], explain: "Akkusativ, weil man das Buch kauft → „das“.", level: "B1" },
      { prompt: "Die Frau, ___ ich geholfen habe, ist Ärztin.", options: ["die","der","deren"], correct: [1], explain: "„helfen“ verlangt den Dativ → „der“.", level: "B1" },
      { prompt: "Der Kollege, ___ Auto kaputt ist, kommt zu spät.", options: ["dessen","deren","dem"], correct: [0], explain: "Besitz bei männlichem Bezugswort → Genitiv „dessen“.", level: "B2" },
      { prompt: "Die Firma, bei ___ er arbeitet, zieht um.", options: ["der","die","deren"], correct: [0], explain: "Nach „bei“ steht der Dativ → „bei der“.", level: "B2" },
      { prompt: "Es gab kaum jemanden, ___ nicht widersprochen hätte.", options: ["der","den","dem"], correct: [0], explain: "Subjekt des Relativsatzes → „der“; der Konjunktiv gehört zur gehobenen Schriftsprache.", level: "C2" },
    ],
    artikel: [
      { prompt: "___ Freundschaft", options: ["der","die","das"], correct: [1], explain: "Wörter auf -schaft sind fast immer „die“.", level: "A2" },
      { prompt: "___ Mädchen", options: ["der","die","das"], correct: [2], explain: "Verkleinerungen auf -chen sind immer „das“ — auch wenn die Person weiblich ist.", level: "A2" },
      { prompt: "___ Frühling", options: ["der","die","das"], correct: [0], explain: "Jahreszeiten, Monate und Wochentage sind „der“.", level: "A1" },
      { prompt: "___ Wasser", options: ["der","die","das"], correct: [2], explain: "„das Wasser“ — wie die meisten Stoffnamen ohne Endung.", level: "A1" },
      { prompt: "___ Zeitung", options: ["der","die","das"], correct: [1], explain: "Wörter auf -ung sind „die“.", level: "A1" },
    ],
    konnektoren: [
      { prompt: "Ich mag ___ Kaffee ___ Tee — beides gern.", options: ["sowohl … als auch","weder … noch","entweder … oder"], correct: [0], explain: "„sowohl … als auch“ verbindet zwei zutreffende Dinge.", level: "B2" },
      { prompt: "Er hat ___ angerufen ___ geschrieben — nichts.", options: ["weder … noch","sowohl … als auch","je … desto"], correct: [0], explain: "„weder … noch“ verneint beide Möglichkeiten.", level: "B2" },
      { prompt: "___ du kommst mit, ___ du bleibst hier.", options: ["Entweder … oder","Weder … noch","Zwar … aber"], correct: [0], explain: "„Entweder … oder“ stellt zwei Möglichkeiten gegenüber.", level: "B2" },
      { prompt: "Der Plan ist ___ teuer, ___ er spart langfristig Geld.", options: ["zwar … aber","weder … noch","sowohl … als auch"], correct: [0], explain: "„zwar … aber“ räumt etwas ein und schränkt es dann ein.", level: "C1" },
    ],
    jedesto: [
      { prompt: "Je länger die Sitzung dauerte, ___ unruhiger wurden alle.", options: ["desto","als","umso mehr"], correct: [0], explain: "Nach „je …“ folgt „desto“ oder „umso“ mit dem Komparativ.", level: "B2" },
      { prompt: "Je genauer man hinsieht, ___ weniger eindeutig wirkt das Ergebnis.", options: ["umso","als","so"], correct: [0], explain: "„umso“ ist gleichwertig zu „desto“.", level: "C1" },
    ],
    wortpaare: [
      { prompt: "Ich ___ ihn schon lange — wir sind befreundet.", options: ["kenne","weiß","kann"], correct: [0], explain: "Personen und Orte „kennt“ man; Fakten „weiß“ man.", level: "A2" },
      { prompt: "Ich ___ nicht, wie spät es ist.", options: ["weiß","kenne","kann"], correct: [0], explain: "Bei einer Information steht „wissen“.", level: "A2" },
      { prompt: "Das Wetter ist heute schlechter ___ gestern.", options: ["als","wie","denn"], correct: [0], explain: "Beim Vergleich mit Unterschied steht „als“.", level: "B1" },
      { prompt: "Er ist genauso groß ___ sein Bruder.", options: ["wie","als","denn"], correct: [0], explain: "Bei Gleichheit steht „wie“.", level: "B1" },
      { prompt: "Sie legte Wert ___ Pünktlichkeit.", options: ["auf","an","in"], correct: [0], explain: "Feste Verbindung: „Wert legen auf“ + Akkusativ.", level: "C1" },
    ],
  };
  CATEGORIES.forEach((cat) => {
    const original = cat.getBank;
    cat.getBank = function (...args) {
      const bank = original.apply(this, args) || [];
      const extra = EXERCISE_EXTRA[cat.id] || [];
      if (!extra.length) return bank;
      // Themen-gefilterte Kategorien (Quiz, Wortschatz): nur Zusatzfragen mit
      // passendem Thema anhängen, sonst tauchten sie in jedem Thema auf.
      const thema = args[0];
      const passend = extra.filter((q) => !thema || q.topic === thema);
      const vorhanden = new Set(bank.map((q) => q.prompt));
      return bank.concat(passend.filter((q) => !vorhanden.has(q.prompt)));
    };
  });

  function historyStand() { return HISTORY_STAND; }
  function historyBatchKey() { return HISTORY_BATCH; }
  function historyPending() { return HISTORY_NEU; }
  function historyDayCount() { return Object.keys(GERMAN_HISTORY_TODAY).length; }

